#!/usr/bin/env node
/**
 * sync-bundle.mjs —— 把 agent.cordis.yml 编译进 cordis.patch.yml 的 preset 声明行。
 *
 *   node scripts/sync-bundle.mjs           # 重写 cordis.patch.yml 里 plugins: 那一块
 *   node scripts/sync-bundle.mjs --check   # 只校验，不写盘（CI 与 tests/bundle.test.mjs 用）
 *
 * 为什么需要它：DSH 0.2 起不再扫描 `<dshHome>/.agent-presets/<id>/`。preset 现在是一条
 * bundle patch 里 `@deepseek-ai/dsh-agent-preset` 行的 `config.plugins` 列表——注册表
 * **不扫描目录，也没有任何接口接受 YAML 写回**（见 dsh-agent-preset-registry 的 README）。
 *
 * 所以把「工具面」和「人设」分开存：
 *
 *   agent.cordis.yml   人设与工具面（人读、人改，保留全部注释）
 *   package.json       dsh.bundle.patch 与 dsh.preset 元信息
 *   cordis.patch.yml   ← 本脚本生成：preset 声明行 + agent.cordis.yml 的正文
 *
 * 引擎模块（luna-*.mjs）仍然以相对路径 `./luna-soul.mjs` 引用：它们是 npm 安装时随包
 * 一起落进 profile 的 `node_modules/dsh-character-presets/`，与 agent.cordis.yml 同级。
 */
import { readFile, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const ROOT = join(HERE, '..')

export const SOURCE = 'agent.cordis.yml'
export const TARGET = 'cordis.patch.yml'
/** 自己这个包的包名：正文里的相对路径要改写成 `<包名>/<文件名>`。 */
export const PACKAGE_NAME = 'dsh-character-presets'
/**
 * 正文在 cordis.patch.yml 里的缩进。
 *
 * 必须严格大于 `config:` 所在的列（24 列）——YAML 的列号是四格一档算的，
 * 缩进不够时 Loader 报 `bad indentation of a mapping entry`（第一次生成就踩过）。
 */
export const BODY_INDENT = '                '

const HEADER = `# GENERATED by scripts/sync-bundle.mjs — do not edit by hand.
#
# This is the \`dsh.bundle.patch\` layer. It declares ONE agent preset to the
# \`agent-presets\` registry and composes it from the rows in agent.cordis.yml.
#
# Edit agent.cordis.yml (persona text, tool rows) or the \`dsh.preset\` block in
# package.json (the name shown in the preset picker), then run:
#
#   node scripts/sync-bundle.mjs
#
# \`engine\` names the preset id that written memory belongs to. Sessions switch
# models and profiles; a memory file keyed by preset id survives that, a file
# keyed by package directory does not.
`

/** 把 agent.cordis.yml 的正文整体缩进，塞进 group 的 config 列表。 */
export function bodyOf(source, indent = BODY_INDENT) {
  const lines = source.split(/\r?\n/)
  const start = lines.findIndex((line) => line.startsWith('- id: '))
  if (start === -1) throw new Error(`${SOURCE}: 找不到顶层插件行（- id: ...）`)
  const head = lines.slice(0, start)
  if (head.some((line) => /^\s*plugins:/.test(line))) {
    throw new Error(`${SOURCE}: 正文里出现了 plugins: 键，会和生成的列表冲突`)
  }
  return lines
    .slice(start)
    .map((line) => (line.trim() === '' ? '' : indent + line))
    .join('\n')
    .replace(/\n+$/, '')
}

/**
 * 把 `name: './x.mjs'` 改写成 `name: 'dsh-character-presets/x.mjs'`。
 *
 * 相对路径换不来依赖：bundle patch 生效后，`./luna-soul.mjs` 会按 profile 目录
 * （或宿主安装目录）解析，而不是按本包目录——实测 `dsh plugin add` 装完，
 * 组合里的名字原样是 `./luna-soul.mjs`，那个文件在 profile 根下并不存在。
 * 写成包名路径，解析走的是包的 exports（见 package.json 的 "./*"）。
 */
export function rewriteRelativeNames(text) {
  return text
    .split('\n')
    .map((line) => {
      const m = /^(\s*name:\s*)\.\/([^'\s]+)\s*$/.exec(line)
      return m === null ? line : m[1] + "'" + PACKAGE_NAME + '/' + m[2] + "'"
    })
    .join('\n')
}

/** 生成完整的 cordis.patch.yml。 */
export function render(meta, source) {
  const preset = meta.dsh.preset ?? {}
  for (const key of ['name', 'description']) {
    if (typeof preset[key] !== 'string' || preset[key].length === 0) {
      throw new Error(`package.json: dsh.preset.${key} 必须是非空字符串`)
    }
  }
  const order = Number.isInteger(preset.order) ? `\n        order: ${preset.order}` : ''
  // description 用 YAML 单引号标量：里面的单引号写成 ''，其余字符原样保留。
  const description = `'${preset.description.replace(/'/g, "''")}'`
  return rewriteRelativeNames(`${HEADER}- insert:
    - id: preset-${preset.id}
      name: '@deepseek-ai/dsh-agent-preset'
      config:
        id: ${preset.id}
        name: ${preset.name}
        description: ${description}${order}
        plugins:
          - id: preset
            name: cordis:group
            group: true
            config:
${bodyOf(source)}`)
}

export async function build(root = ROOT) {
  const meta = JSON.parse(await readFile(join(root, 'package.json'), 'utf8'))
  const source = await readFile(join(root, SOURCE), 'utf8')
  const missing = ['bundle', 'preset'].filter((key) => meta.dsh?.[key] === undefined)
  if (missing.length > 0) {
    throw new Error(`package.json: 缺少 dsh.${missing.join(' / dsh.')} —— 见 README「打包成插件」`)
  }
  return render(meta, source)
}

const invokedDirectly = process.argv[1] !== undefined &&
  fileURLToPath(import.meta.url) === process.argv[1]

if (invokedDirectly) {
  const check = process.argv.includes('--check')
  try {
    const next = await build()
    const path = join(ROOT, TARGET)
    let current = ''
    try { current = await readFile(path, 'utf8') } catch { /* 第一次生成 */ }
    if (next === current) {
      console.log(`${TARGET}: 已是最新`)
    } else if (check) {
      console.error(`${TARGET}: 与 ${SOURCE} 不一致 —— 运行 node scripts/sync-bundle.mjs`)
      process.exit(1)
    } else {
      await writeFile(path, next, 'utf8')
      console.log(`${TARGET}: 已按 ${SOURCE} 重新生成`)
    }
  } catch (error) {
    console.error(`[fail] ${error.message}`)
    process.exit(1)
  }
}
